    for dr,dc,col in pat:
        out[pr+dr][pc+dc]=col
    ph=max(dr for dr,_,_ in pat)+1; pw=max(dc for _,dc,_ in pat)+1
    # center of pattern
    cr,cc=pr+ph//2, pc+pw//2
    cells=[(dr-ph//2, dc-pw//2, col) for dr,dc,col in pat]
    for r in range(H):
        for c in range(W):
            if g[r][c]==anchor:
                # skip if overlaps original pattern bbox
                top=cr-ph//2; left=cc-pw//2
                if not (r+ph//2 < pr or r-ph//2 > pr+ph-1 or c+pw//2 < pc or c-pw//2 > pc+pw-1):
                    continue
                for dr,dc,col in cells:
                    rr,rc=r+dr,c+dc
                    if 0<=rr<H and 0<=rc<W:
                        out[rr][rc]=col
    return out

